import{_ as o,o as i,c as a,a2 as n}from"./chunks/framework.BN2sqjC1.js";const v=JSON.parse('{"title":"Presenza: chi altro è nel documento","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/presenza.md","filePath":"user-guide/presenza.md"}'),t={name:"user-guide/presenza.md"};function s(l,e,r,c,d,u){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="presenza-chi-altro-e-nel-documento" tabindex="-1">Presenza: chi altro è nel documento <a class="header-anchor" href="#presenza-chi-altro-e-nel-documento" aria-label="Permalink to &quot;Presenza: chi altro è nel documento&quot;">​</a></h1><p>Nei <strong>vault condivisi</strong> vedete chi altro ha aperto lo stesso documento e dove tiene il puntatore. Non è la modifica simultanea: le modifiche si uniscono come sempre alla sincronizzazione (vedi <a href="./condivisione-gruppi.html">Condivisione e gruppi</a>).</p><h2 id="cosa-si-vede" tabindex="-1">Cosa si vede <a class="header-anchor" href="#cosa-si-vede" aria-label="Permalink to &quot;Cosa si vede&quot;">​</a></h2><ul><li><strong>Gli avatar</strong> nella barra dell&#39;Esplora file (dove prima c&#39;era il pulsante «Nuova applicazione», che resta nella ribbon, nei menu contestuali, nella palette e nello stato vuoto): un cerchio con le iniziali per ogni altro utente che ha aperto il file in primo piano. Se non c&#39;è nessuno, la barra non mostra nulla. Passando sopra un avatar si legge il nome.</li><li><strong>Quattro avatar al massimo.</strong> Gli altri diventano un badge <code>+N</code> (per esempio <code>+2</code>), con i nomi nel suggerimento.</li><li><strong>I cursori</strong>, sopra il documento: un puntatore con l&#39;etichetta del nome, che segue il mouse di quell&#39;utente. Ci sono per <strong>note, disegni e canvas</strong>; per lettura, basi, PDF, immagini e applicazioni si vedono solo gli avatar.</li><li><strong>Nelle note</strong> il cursore indica la riga e la colonna del testo sotto il <strong>puntatore del mouse</strong>, non il punto in cui si sta scrivendo. In Live Preview la riga è esatta e la colonna è approssimata dentro un blocco. Nei <strong>disegni</strong> e nei <strong>canvas</strong> il cursore sta nello stesso punto della scena anche se zoom e scroll sono diversi dai vostri.</li><li><strong>Il colore</strong> di una persona è sempre lo stesso: avatar, puntatore ed etichetta, in ogni file e ogni sessione, su tutti i dispositivi. Il colore non dipende da chi guarda.</li><li>Con la riduzione del movimento del sistema attiva, il puntatore non scivola: salta nella nuova posizione.</li></ul><h2 id="chi-vedete" tabindex="-1">Chi vedete <a class="header-anchor" href="#chi-vedete" aria-label="Permalink to &quot;Chi vedete&quot;">​</a></h2><ul><li><strong>Solo altri utenti.</strong> Non vedete voi stessi, né un vostro secondo dispositivo con lo stesso account.</li><li><strong>Solo nei vault condivisi</strong> (e nei mount). I vault privati non hanno presenza: nessun altro utente li apre e il server non conosce i percorsi.</li><li><strong>Solo chi può leggere quel file.</strong> Se condividete una cartella, vedete gli altri solo sui file di quella cartella. Se il vostro accesso viene revocato, gli avatar e i cursori di quel file spariscono.</li><li><strong>Solo i file già sincronizzati.</strong> Una nota appena creata e non ancora sincronizzata non ha presenza finché il cloud non la conosce.</li><li>Serve il collegamento al cloud: da offline non si vede nulla e al ritorno online la presenza riparte da sola.</li></ul><h2 id="privacy-chi-vede-cosa" tabindex="-1">Privacy: chi vede cosa <a class="header-anchor" href="#privacy-chi-vede-cosa" aria-label="Permalink to &quot;Privacy: chi vede cosa&quot;">​</a></h2><p>Gli altri utenti dello stesso file vedono <strong>il vostro nome visualizzato</strong> e <strong>la posizione del puntatore</strong> finché il file è aperto in primo piano. Quando lo chiudete, cambiate scheda o vi disconnettete, spariscono. <strong>Niente viene salvato</strong>: la presenza vive solo in memoria del server, non è nel registro di audit né nei log (vedi <a href="./../security/data-retention.html">conservazione dei dati</a>). Gli amministratori non la vedono in nessuna schermata.</p><h2 id="come-si-spegne" tabindex="-1">Come si spegne <a class="header-anchor" href="#come-si-spegne" aria-label="Permalink to &quot;Come si spegne&quot;">​</a></h2><p>Si spegne per tutti gli utenti di un profilo: l&#39;amministratore imposta <code>features.presence</code> a <code>false</code> nel Config Profile (<a href="./../admin-guide/profili-quote-audit.html">guida dell&#39;amministratore</a>). Vale anche a caldo, senza riavviare l&#39;app: gli avatar e i cursori spariscono e il client chiude la connessione. Non c&#39;è un&#39;impostazione personale per spegnerla.</p><h2 id="se-non-vedete-nessuno" tabindex="-1">Se non vedete nessuno <a class="header-anchor" href="#se-non-vedete-nessuno" aria-label="Permalink to &quot;Se non vedete nessuno&quot;">​</a></h2><p>Controllate che il vault sia condiviso e collegato, che l&#39;altro utente abbia lo stesso file aperto in primo piano (non solo in una scheda in secondo piano), che sia online e che la presenza non sia spenta dal profilo. Altri sintomi: <a href="./risoluzione-problemi.html">risoluzione dei problemi</a>.</p>',12)])])}const h=o(t,[["render",s]]);export{v as __pageData,h as default};
